from typing import List

def largest_prime_sum(lst: List[int]) -> int:
    from math import sqrt

    def is_prime(n):
        if n <= 1:
            return False
        for i in range(2, int(sqrt(n)) + 1):
            if n % i == 0:
                return False
        return True

    largest_prime = -1
    current_sum = 0
    for num in lst:
        if is_prime(num) and num > largest_prime:
