def do_algebra(operator, operand):
    # Convert the operand list into a list of numbers for easier processing
    operand = [int(num) for num in operand]

    # Initialize the result with the first element from the operand list
    result = operand[0]

    # Iterate through each operator and operand pair
    for i, (op, *rest) in enumerate(zip(operator, operand)):
        if op == '+':
            result += rest[0]
        elif op == '-':
            result -= rest[0]
        elif op == '*':
            result *= rest[0]
        elif op == '//':
            result //= rest[0]
        elif op == '**':
            result **= rest[0]

    return result
