def max_product(nums):
    """
    Find the maximum product of any two numbers in the given list.

    Args:
        nums (list): A list of integers.

    Returns:
        int: The maximum product of any two numbers.
    """
    if len(nums) < 2:
        raise ValueError("The input array must contain at least two elements.")

    max1, max2 = float('-inf'), float('-inf')
    min1, min2 = float('inf'), float('inf')

    for num in nums:
        if num > max1:
            max2, max1 = max1, num
        elif num > max2:
            max2 = num

        if num < min1:
            min2, min1 = min1, num
        elif num < min2:
            min2 = num

    return max(max1 * max2, min1 * min2)

# Example usage
